import random
random.seed(0)
# 스텁 프로그램: 지시문 i 와 데모 묶음 d 의 '진짜 품질'(모른다고 친다)
TRUE_I, TRUE_D = [0.50, 0.65, 0.55], [0.0, 0.10, 0.05]
def minibatch_score(i, d, n=10):          # 미니배치 10개 정확도(잡음 있음)
    return sum(random.random() < TRUE_I[i] + TRUE_D[d] for _ in range(n)) / n
stats = {("I", k): [0, 0.0] for k in range(3)} | {("D", k): [0, 0.0] for k in range(3)}
def belief(key):                           # 관측 평균(낙관적 초기값 0.6)
    n, s = stats[key]; return (s + 0.6) / (n + 1)
def pick(kind):                            # 대체로 믿음이 높은 쪽, 가끔 탐험
    if random.random() < 0.3: return random.randrange(3)
    return max(range(3), key=lambda k: belief((kind, k)))
for t in range(40):
    i, d = pick("I"), pick("D")
    s = minibatch_score(i, d)
    for key in (("I", i), ("D", d)):
        stats[key][0] += 1; stats[key][1] += s
for kind in "ID":
    print(kind, [(k, stats[(kind, k)][0], round(belief((kind, k)), 2)) for k in range(3)])
i, d = (max(range(3), key=lambda k: belief((kind, k))) for kind in "ID")
print("최종 후보: 지시문", i, "데모", d, "-> 전체 평가", minibatch_score(i, d, n=200))

import numpy as np
def group_adv(r, eps=1e-6):
    r = np.asarray(r, float)
    return (r - r.mean()) / (r.std() + eps)        # 그룹 안 z-점수(모집단 표준편차)

for r in ([0.7, 0.6, 0.3, 0.2, 0.2], [1, 0, 0, 0], [1, 1, 1, 1]):
    print(r, "->", np.round(group_adv(r), 3))

def clipped(ratio, A, eps=0.2):                   # 토큰 하나의 PPO/GRPO 대리 목적
    return np.minimum(ratio * A, np.clip(ratio, 1 - eps, 1 + eps) * A)

A = group_adv([0.7, 0.6, 0.3, 0.2, 0.2])
for ratio, a in ((1.3, A[0]), (0.7, A[3]), (1.1, A[0])):
    print(f"ratio={ratio} A={a:.3f} -> {clipped(ratio, a):.3f}")

def kl_k3(logp, logp_ref):                         # 토큰별 KL 추정(k3, 노트 보충)
    d = logp_ref - logp
    return np.exp(d) - d - 1
print("KL k3:", np.round(kl_k3(np.log([.5, .7]), np.log([.4, .7])), 4))

